// writeCompactTranscript converts the already-redacted full transcript into the
// condensed transcript.jsonl format and adds it to the checkpoint entries.
// Best-effort: a conversion or blob failure is logged and never blocks the
// checkpoint write — full.jsonl remains the source of truth.
func (s *GitStore) writeCompactTranscript(ctx context.Context, opts WriteCommittedOptions, basePath string, transcriptBytes []byte, entries map[string]object.TreeEntry) {
	compacted, err := transcriptcompact.Compact(redact.AlreadyRedacted(transcriptBytes), transcriptcompact.MetadataFields{
		Agent:      compactAgentName(opts.Agent),
		CLIVersion: versioninfo.Version,
	})
	if err != nil {
		logging.Warn(ctx, "failed to generate compact transcript, skipping transcript.jsonl",
			slog.String("session_id", opts.SessionID),
			slog.String("checkpoint_id", opts.CheckpointID.String()),
			slog.String("error", err.Error()))
		return
	}
	if len(compacted) == 0 {
		return
	}

	blobHash, err := CreateBlobFromContent(s.repo, compacted)
	if err != nil {
		logging.Warn(ctx, "failed to write compact transcript blob, skipping transcript.jsonl",
			slog.String("session_id", opts.SessionID),
			slog.String("checkpoint_id", opts.CheckpointID.String()),
			slog.String("error", err.Error()))
		return
	}
	compactPath := basePath + paths.CompactTranscriptFileName
	entries[compactPath] = object.TreeEntry{
		Name: compactPath,
		Mode: filemode.Regular,
		Hash: blobHash,
	}
}

