// TestWriteCommitted_CompactTranscript verifies that the condensed
// transcript.jsonl is written alongside full.jsonl only when
// strategy_options.push_compact_transcripts is enabled.
func TestWriteCommitted_CompactTranscript(t *testing.T) {
	t.Parallel()

	transcriptJSONL := `{"type":"user","message":{"role":"user","content":"hello"}}` + "\n" +
		`{"type":"assistant","message":{"id":"msg_1","role":"assistant","content":[{"type":"text","text":"hi"}],"usage":{"input_tokens":3,"output_tokens":5}}}` + "\n"

	tests := []struct {
		name        string
		settings    string
		wantCompact bool
	}{
		{"Enabled", `{"enabled": true, "strategy_options": {"push_compact_transcripts": true}}`, true},
		{"DisabledByDefault", `{"enabled": true}`, false},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			t.Parallel()
			repo, _ := setupBranchTestRepo(t)
			worktree, err := repo.Worktree()
			require.NoError(t, err)
			repoRoot := worktree.Filesystem().Root()

			require.NoError(t, os.MkdirAll(filepath.Join(repoRoot, ".entire"), 0o755))
			require.NoError(t, os.WriteFile(filepath.Join(repoRoot, ".entire", "settings.json"), []byte(tt.settings), 0o644))

			ctx := settings.WithWorktreeRoot(context.Background(), repoRoot)
			store := NewGitStore(repo, DefaultV1Refs())
			checkpointID := id.MustCheckpointID("a1b2c3d4e5f6")
			require.NoError(t, store.WriteCommitted(ctx, WriteCommittedOptions{
				CheckpointID: checkpointID,
				SessionID:    "compact-test-session",
				Strategy:     "manual-commit",
				Agent:        agent.AgentTypeClaudeCode,
				Transcript:   redact.AlreadyRedacted([]byte(transcriptJSONL)),
				AuthorName:   "Test Author",
				AuthorEmail:  "test@example.com",
			}))

			ref, err := repo.Reference(plumbing.NewBranchReferenceName(paths.MetadataBranchName), true)
			require.NoError(t, err)
			commit, err := repo.CommitObject(ref.Hash())
			require.NoError(t, err)
			tree, err := commit.Tree()
			require.NoError(t, err)
			sessionTree, err := tree.Tree(checkpointID.Path() + "/0")
			require.NoError(t, err)

			// full.jsonl is written regardless of the option.
			_, err = sessionTree.File(paths.TranscriptFileName)
			require.NoError(t, err)

			compactFile, err := sessionTree.File(paths.CompactTranscriptFileName)
			if !tt.wantCompact {
				require.Error(t, err, "transcript.jsonl should not be written when push_compact_transcripts is off")
				return
			}
			require.NoError(t, err)
			content, err := compactFile.Contents()
			require.NoError(t, err)
			require.Contains(t, content, `"agent":"claude-code"`)
			require.Contains(t, content, `"type":"assistant"`)
		})
	}
}

